	input [13:0] chr_ain,     // chr address in
	output [21:0] chr_aout_b,  // chr address out
	input        chr_read,    // chr ram read
	output        chr_allow_b, // chr allow write
	output        vram_a10_b,  // Value for A10 address line
	output        vram_ce_b,   // True if the address should be routed to the internal 2kB VRAM.
	output        irq_b,       // IRQ
	input [15:0] audio_in,    // Inverted audio from APU
	output [15:0] audio_b,     // Mixed audio output
	output [15:0] flags_out_b, // flags {0, 0, 0, 0, has_savestate, prg_conflict, prg_bus_write, has_chr_dout}
	// savestates              
	input       [63:0]  SaveStateBus_Din,
	input       [ 9:0]  SaveStateBus_Adr,
	input               SaveStateBus_wren,
	input               SaveStateBus_rst,
	input               SaveStateBus_load,
	output      [63:0]  SaveStateBus_Dout
);
// ---- declarations hoisted by syn/tools/prep.py ----
wire [21:0] prg_aout, chr_aout;
wire prg_allow;
wire chr_allow;
wire vram_a10;
wire vram_ce;
wire [63:0] SS_MAP1;
wire [63:0] SS_MAP1_BACK;	

assign prg_aout_b   = enable ? prg_aout: '0;
assign prg_dout_b   = enable ? 8'hFF: '1;
assign prg_allow_b  = enable ? prg_allow: '0;
assign chr_aout_b   = enable ? chr_aout: '0;
assign chr_allow_b  = enable ? chr_allow: '0;
assign vram_a10_b   = enable ? vram_a10: '0;
assign vram_ce_b    = enable ? vram_ce: '0;
assign irq_b        = enable ? 1'b0: '0;
assign flags_out_b  = enable ? flags_out: '0;
assign audio_b      = enable ? {1'b0, audio_in[15:1]}: '0;

// (hoisted) wire [21:0] prg_aout, chr_aout;
// (hoisted) wire prg_allow;
// (hoisted) wire chr_allow;
// (hoisted) wire vram_a10;
// (hoisted) wire vram_ce;
reg [15:0] flags_out = {12'h0, 1'b1, 3'b0};

reg [3:0] prg_bank;
reg ciram_select;
wire mapper232 = (flags[7:0] == 232);
always @(posedge clk)
if (~enable) begin
	prg_bank <= 0;
	ciram_select <= 0;
end else if (SaveStateBus_load) begin
	prg_bank     <= SS_MAP1[ 3: 0];
	ciram_select <= SS_MAP1[    4];
end else if (ce) begin
	if (prg_ain[15] && prg_write) begin
		if (!prg_ain[14] && mapper232) // $8000-$BFFF Outer bank select (only on iNES 232)
			prg_bank[3:2] <= prg_din[4:3];
		if (prg_ain[14:13] == 0)       // $8000-$9FFF Fire Hawk Mirroring
			ciram_select <= prg_din[4];
		if (prg_ain[14])               // $C000-$FFFF Bank select
			prg_bank <= {mapper232 ? prg_bank[3:2] : prg_din[3:2], prg_din[1:0]};
	end
end

assign SS_MAP1_BACK[ 3: 0] = prg_bank;
assign SS_MAP1_BACK[    4] = ciram_select;
assign SS_MAP1_BACK[63: 5] = 59'b0; // free to be used

reg [3:0] prgout;
always @* begin
	casez({prg_ain[14], mapper232})
		2'b0?: prgout = prg_bank;
		2'b10: prgout = 4'b1111;
		2'b11: prgout = {prg_bank[3:2], 2'b11};
	endcase
end

assign prg_aout = {4'b00_00, prgout, prg_ain[13:0]};
assign prg_allow = prg_ain[15] && !prg_write;
assign chr_allow = flags[15];
assign chr_aout = {9'b10_0000_000, chr_ain[12:0]};
assign vram_ce = chr_ain[13];
// XXX(ludde): Fire hawk uses flags[14] == 0 while no other game seems to do that.
// So when flags[14] == 0 we use ciram_select instead.
assign vram_a10 = flags[14] ? chr_ain[10] : ciram_select;

// savestate
// (hoisted) wire [63:0] SS_MAP1;
// (hoisted) wire [63:0] SS_MAP1_BACK;	
wire [63:0] SaveStateBus_Dout_active;	
eReg_SavestateV #(SSREG_INDEX_MAP1, 64'h0000000000000000) iREG_SAVESTATE_MAP1 (clk, SaveStateBus_Din, SaveStateBus_Adr, SaveStateBus_wren, SaveStateBus_rst, SaveStateBus_Dout_active, SS_MAP1_BACK, SS_MAP1);  

assign SaveStateBus_Dout = enable ? SaveStateBus_Dout_active : 64'h0000000000000000;

endmodule

